#include "Pcm.h"
#include <RetroMediaLab/MediaEngine/Diagnostics.h>
#include <QtEndian>
#include <algorithm>
#include <cmath>
#include <bit>
namespace RetroMediaLab::MediaEngine::TapePcm {
double roundEven(double value){const auto base=std::floor(value),fraction=value-base;return fraction>Constants::Half||(fraction==Constants::Half&&std::fmod(base,Constants::EvenDivisor)!=0)?base+1:base;}
std::vector<std::int32_t> extractChannel(std::span<const std::uint8_t> pcm,int channels,int bits,int align,int channel){using namespace Constants;if(channel<0||channel>=channels||align<=0||pcm.size()%std::size_t(align)||std::find(SupportedBits.begin(),SupportedBits.end(),bits)==SupportedBits.end()||std::int64_t(channels)*(bits/ByteBits)>align)throw MediaError(DiagnosticCode::TapePcmData);const auto width=bits/ByteBits;std::vector<std::int32_t> result(pcm.size()/align);for(std::size_t i=0;i<result.size();++i){const auto* bytes=pcm.data()+i*align+channel*width;switch(bits){case ByteBits:result[i]=int(bytes[0])-Signed8Bias;break;case DefaultBits:result[i]=qFromLittleEndian<std::int16_t>(bytes);break;case TripleBits:{std::uint32_t value=std::uint32_t(bytes[0])|(std::uint32_t(bytes[1])<<ByteBits)|(std::uint32_t(bytes[ThirdByte])<<DefaultBits);if(value&Sign24)value|=Extend24;result[i]=std::bit_cast<std::int32_t>(value);break;}case WordBits:result[i]=qFromLittleEndian<std::int32_t>(bytes);break;}}return result;}
void appendPulses(std::vector<std::int16_t>& samples,std::int16_t& level,std::uint16_t tStates,int count,int rate,int clock){using namespace Constants;if(rate<=0||clock<=0||count<0)throw MediaError(DiagnosticCode::TapePcmData);const auto rounded=roundEven(double(tStates)*rate/clock);if(!std::isfinite(rounded)||rounded>MaximumBuffer)throw MediaError(DiagnosticCode::TapePcmData);const auto size=std::max<std::int64_t>(1,std::int64_t(rounded));if(samples.size()>std::size_t(MaximumBuffer)||size*count>MaximumBuffer||std::uint64_t(size*count)>std::uint64_t(MaximumBuffer)-samples.size())throw MediaError(DiagnosticCode::TapePcmData);for(int pulse=0;pulse<count;++pulse){samples.insert(samples.end(),std::size_t(size),level);level=std::bit_cast<std::int16_t>(std::uint16_t(0-std::uint16_t(level)));}}
void appendSilence(std::vector<std::int16_t>& samples,int rate,double seconds){using namespace Constants;if(rate<=0||!std::isfinite(seconds)||seconds<0)throw MediaError(DiagnosticCode::TapePcmData);const auto count=roundEven(rate*seconds);if(!std::isfinite(count)||count>MaximumBuffer||count>double(MaximumBuffer)-double(samples.size()))throw MediaError(DiagnosticCode::TapePcmData);samples.insert(samples.end(),std::size_t(count),0);}
}
